sql:
SELECT CAST(SUM(CASE WHEN type = 'Community Service' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(event_id) AS percentage_share
FROM event
WHERE event_date BETWEEN '2019-01-01' AND '2019-12-31';

